    "id": "pilares",
    "titulo": "Pilares de contenido",
    "html": "<section id=\"pilares\" data-transition=\"fade\" style=\"background:#F3EDE1;color:#0B2A47;font-family:'Newsreader', Georgia, serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:28px;font-weight:600;letter-spacing:5px;text-transform:uppercase;color:#175F51\">El mapa</p>\n<h2 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:72px;font-weight:700;line-height:1;text-transform:uppercase;letter-spacing:1px;color:#0B2A47\">Pilares de contenido</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px;flex:1\">\n<div style=\"background:#0B2A47;padding:32px;border-radius:12px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:48px;font-weight:700;color:#7FB5A6;line-height:1\">01</p>\n<h3 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:36px;font-weight:700;text-transform:uppercase;color:#F3EDE1;line-height:1.05\">Bodega</h3>\n<p style=\"font-size:26px;line-height:1.35;color:#C8D2DC\">La carta de vinos y sus D.O., contadas por Jenner Bardales.</p>\n</div>\n<div style=\"background:#0B2A47;padding:32px;border-radius:12px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:48px;font-weight:700;color:#7FB5A6;line-height:1\">02</p>\n<h3 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:36px;font-weight:700;text-transform:uppercase;color:#F3EDE1;line-height:1.05\">Salsa garum</h3>\n<p style=\"font-size:26px;line-height:1.35;color:#C8D2DC\">Imprescindible en la casa. Varios garums, en prueba constante.</p>\n</div>\n<div style=\"background:#0B2A47;padding:32px;border-radius:12px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:48px;font-weight:700;color:#7FB5A6;line-height:1\">03</p>\n<h3 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:36px;font-weight:700;text-transform:uppercase;color:#F3EDE1;line-height:1.05\">Charcutería de la casa</h3>\n<p style=\"font-size:26px;line-height:1.35;color:#C8D2DC\">Embutidos propios: txistorra, chicharrón Marín, butifarras.</p>\n</div>\n<div style=\"background:#0B2A47;padding:32px;border-radius:12px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:48px;font-weight:700;color:#7FB5A6;line-height:1\">04</p>\n<h3 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:36px;font-weight:700;text-transform:uppercase;color:#F3EDE1;line-height:1.05\">Propuesta gastronómica</h3>\n<p style=\"font-size:26px;line-height:1.35;color:#C8D2DC\">El paso a paso de cada plato, de la plancha a la mesa.</p>\n</div>\n<div style=\"background:#175F51;padding:32px;border-radius:12px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:48px;font-weight:700;color:#BFE0D6;line-height:1\">05</p>\n<h3 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:36px;font-weight:700;text-transform:uppercase;color:#F3EDE1;line-height:1.05\">Camisetas Marín</h3>\n<p style=\"font-size:26px;line-height:1.35;color:#DCEBE5\">Arranca la venta online: el equipo las lleva puestas.</p>\n</div>\n<div style=\"background:#175F51;padding:32px;border-radius:12px;display:flex;flex-direction:column;gap:12px\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:48px;font-weight:700;color:#BFE0D6;line-height:1\">06</p>\n<h3 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:36px;font-weight:700;text-transform:uppercase;color:#F3EDE1;line-height:1.05\">El espacio</h3>\n<p style=\"font-size:26px;line-height:1.35;color:#DCEBE5\">La casa de hoy, con la memoria del lugar.</p>\n</div>\n</div>\n<div style=\"position:absolute;left:128px;right:128px;bottom:64px;height:32px;display:flex;flex-direction:row;justify-content:space-between\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:24px;letter-spacing:3px;text-transform:uppercase;color:#5A6676\">Ultramarinos Marín Madrid · Briefing noviembre</p>\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:24px;letter-spacing:3px;text-transform:uppercase;color:#5A6676\">03</p>\n</div>\n</section>"
