    "html": "<section id=\"p1\" data-transition=\"fade\" data-section=\"Pilar 01: la bodega y la propuesta líquida\" style=\"background:#175F51;color:#F3EDE1;font-family:'Newsreader', Georgia, serif;padding:128px;display:flex;flex-direction:column;justify-content:end;gap:24px\">\n<img src=\"/pitch/ultramarinos-briefing/head-light.png\" alt=\"\" style=\"position:absolute;right:96px;top:120px;width:620px;height:730px;object-fit:contain;opacity:0.12\">\n<p style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:220px;font-weight:700;line-height:0.9;color:#7FB5A6\">01</p>\n<h1 style=\"font-family:'Barlow Condensed', Arial, sans-serif;font-size:140px;font-weight:700;line-height:0.95;text-transform:uppercase;letter-spacing:2px;color:#F3EDE1\">Bodega</h1>\n<p style=\"font-size:48px;font-style:italic;line-height:1.25;color:#DCEBE5;width:1100px\">La propuesta líquida: por qué cada vino está en esta carta.</p>\n</section>"
