    "html": "<section id=\"cierre\" data-transition=\"fade\" style=\"background:#F3EDE1;color:#0B2A47;font-family:'Newsreader', Georgia, serif;padding:128px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:56px\">\n<img src=\"/pitch/ultramarinos-briefing/wordmark.png\" alt=\"Ultramarinos Marín\" style=\"width:900px;height:66px;object-fit:contain\">\n<p style=\"font-size:44px;font-style:italic;line-height:1.3;color:#46566A;text-align:center;width:1200px\">Cada publicación, una razón para sentarse a la mesa.</p>\n<hr style=\"width:120px;border:none;border-top:2px solid #175F51;margin:0\">\n<img src=\"/pitch/ultramarinos-briefing/logo-maen.png\" alt=\"maen studios\" style=\"width:560px;height:361px;object-fit:contain\">\n</section>"
